import { afterEach, describe, expect, it, vi } from "vitest";
import type { AudioTrack, VideoTrack } from "../../src/types";

// dist/wasm/movi.js is generated by build:wasm and absent in the unit-test
// job; MoviPlayer's module graph imports it eagerly, so stub the module the
// same way the other MoviPlayer-importing suites (rebuffer-unlock.test.ts,
// video-worker-policy.test.ts) already do.
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));
vi.mock("dashjs", () => ({ MediaPlayer: vi.fn() }));
vi.mock("shaka-player/dist/shaka-player.compiled", () => ({
  default: {
    Player: { isBrowserSupported: vi.fn(() => false) },
    polyfill: { installAll: vi.fn() },
    net: { NetworkingEngine: { RequestType: { LICENSE: 1 } } },
  },
}));

const videoTrack: VideoTrack = {
  id: 0,
  type: "video",
  codec: "hevc",
  width: 1920,
  height: 1080,
  frameRate: 24,
};

const flacTrack: AudioTrack = {
  id: 1,
  type: "audio",
  codec: "flac",
  codecId: 86028,
  channels: 2,
  sampleRate: 48000,
};

function stubBrowserGlobals() {
  vi.stubGlobal("document", {
    hidden: false,
    visibilityState: "visible",
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
  });
  vi.stubGlobal("window", {
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    setInterval,
    clearInterval,
  });
  vi.stubGlobal("requestAnimationFrame", vi.fn(() => 1));
  vi.stubGlobal("cancelAnimationFrame", vi.fn());
}

afterEach(() => {
  vi.unstubAllGlobals();
});

/**
 * A player mid-playback (not rebuffering, not seeking, not catching up),
 * with a real video queue so the video-side backpressure branches stay out
 * of the way — isolates the audio-cushion gate this test is about. Mirrors
 * test/core/rebuffer-unlock.test.ts's "playing normally" fixture exactly.
 */
function playingPlayer(player: unknown, audioBuffered: number) {
  const readPacket = vi.fn(async () => null);
  Object.assign(player as Record<string, unknown>, {
    demuxer: { readPacket },
    mediaInfo: { duration: 1422, videoFrameRate: 24 },
    wasPlayingBeforeRebuffer: false,
    _bufferingEntryTime: performance.now() - 1000,
    _playStartTime: performance.now() - 20_000,
    waitingForVideoSync: false,
    seekTargetTime: -1,
    seekDemuxAheadTime: -1,
    justSeeked: false,
    seekTime: 0,
    disableAudio: false,
    muted: false,
    eofReached: false,
    demuxInFlight: false,
    isBackgrounded: false,
    isPiPActive: false,
    _primingAudio: false,
    _videoResumeTarget: -1,
    videoDecoder: {
      isSoftware: false,
      queueSize: 0,
      isWaitingForKeyframe: false,
      isRecentlyRecovering: () => false,
      keyframeWaitMs: () => 0,
      flush: vi.fn(),
    },
    audioDecoder: {
      isSoftware: true,
      queueSize: 0,
      getStats: () => ({ worker: { queueDepth: 0 } }),
      canBatch: () => false,
      decode: vi.fn(),
    },
    videoRenderer: {
      getQueueSize: () => 30,
      stopPresentationLoop: vi.fn(),
      getHeadFrameTime: () => 12,
    },
    audioRenderer: {
      getBufferedDuration: () => audioBuffered,
      isRebuffering: () => false,
      isDroppingAudio: () => false,
      isUnderrunning: () => false,
      getAudioClock: () => -1,
      getMaxScheduledMediaTime: () => 0,
      resumeFromBuffering: vi.fn(),
    },
  });
  return readPacket;
}

/**
 * P4 — `maxAudioBuffered = (isAudioSoftware ? 5.0 : ...) * rateScale`, where
 * `rateScale = rate < 1.0 ? 1.0 / rate : Math.min(2.0, rate)` (MoviPlayer.ts,
 * the "P4 — recomputed for the post-A5 architecture" block). Since A5 made
 * `needsSoftwareDecoding()` unconditional, isAudioSoftware is true for every
 * audio track now, so the base is always 5.0s and rate is the only variable
 * left — these tests pin the boundary at each rate regime docs/PLAN_MERGE.MD
 * calls out (1x, slow, fast-capped).
 */
describe("MoviPlayer P4: maxAudioBuffered backpressure boundary", () => {
  async function makePlayer(rate: number) {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    player.trackManager.setTracks([videoTrack, flacTrack]);
    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    (player as any).clock.setPlaybackRate(rate);
    return player;
  }

  it("at 1x, reads while the audio cushion sits just under the 5.0s target", async () => {
    const player = await makePlayer(1.0);
    const readPacket = playingPlayer(player, 4.99);
    await (player as any).processLoop();
    expect(readPacket).toHaveBeenCalled();
  }, 20_000);

  it("at 1x, stops reading once the audio cushion clears the 5.0s target", async () => {
    const player = await makePlayer(1.0);
    const readPacket = playingPlayer(player, 5.01);
    await (player as any).processLoop();
    expect(readPacket).not.toHaveBeenCalled();
  }, 20_000);

  it("at 0.5x, the target doubles to 10.0s (rateScale = 1/rate)", async () => {
    const player = await makePlayer(0.5);
    const under = playingPlayer(player, 9.99);
    await (player as any).processLoop();
    expect(under).toHaveBeenCalled();

    const player2 = await makePlayer(0.5);
    const over = playingPlayer(player2, 10.01);
    await (player2 as any).processLoop();
    expect(over).not.toHaveBeenCalled();
  }, 20_000);

  it("at 1.5x, the target scales proportionally to 7.5s (rateScale = rate, uncapped below 2x)", async () => {
    const player = await makePlayer(1.5);
    const under = playingPlayer(player, 7.49);
    await (player as any).processLoop();
    expect(under).toHaveBeenCalled();

    const player2 = await makePlayer(1.5);
    const over = playingPlayer(player2, 7.51);
    await (player2 as any).processLoop();
    expect(over).not.toHaveBeenCalled();
  }, 20_000);

  it("at 4x, rateScale is capped at 2.0 (target stays 10.0s, not 20.0s)", async () => {
    const player = await makePlayer(4.0);
    const under = playingPlayer(player, 9.99);
    await (player as any).processLoop();
    expect(under).toHaveBeenCalled();

    const player2 = await makePlayer(4.0);
    const over = playingPlayer(player2, 10.01);
    await (player2 as any).processLoop();
    expect(over).not.toHaveBeenCalled();
  }, 20_000);
});
